// src/svg/project.ts
function fitProjection(bbox, width, height, padding = 8) {
  const [minLng, minLat, maxLng, maxLat] = bbox;
  const midLat = (minLat + maxLat) / 2;
  const kx = Math.cos(midLat * Math.PI / 180);
  const geoW = (maxLng - minLng) * kx || 1e-6;
  const geoH = maxLat - minLat || 1e-6;
  const availW = Math.max(1, width - padding * 2);
  const availH = Math.max(1, height - padding * 2);
  const scale = Math.min(availW / geoW, availH / geoH);
  const drawW = geoW * scale;
  const drawH = geoH * scale;
  const offsetX = padding + (availW - drawW) / 2;
  const offsetY = padding + (availH - drawH) / 2;
  return {
    width,
    height,
    project(lng, lat) {
      const x = offsetX + (lng - minLng) * kx * scale;
      const y = offsetY + (maxLat - lat) * scale;
      return [x, y];
    }
  };
}

// src/core/geo.ts
function eachRing(geom, fn) {
  if (geom.type === "Polygon") {
    for (const ring of geom.coordinates) fn(ring);
  } else {
    for (const poly of geom.coordinates) for (const ring of poly) fn(ring);
  }
}
function bboxOf(fc) {
  let minLng = Infinity, minLat = Infinity, maxLng = -Infinity, maxLat = -Infinity;
  for (const f of fc.features) {
    eachRing(f.geometry, (ring) => {
      for (const [lng, lat] of ring) {
        if (lng < minLng) minLng = lng;
        if (lat < minLat) minLat = lat;
        if (lng > maxLng) maxLng = lng;
        if (lat > maxLat) maxLat = lat;
      }
    });
  }
  if (!Number.isFinite(minLng)) throw new Error("bboxOf: empty geometry");
  return [minLng, minLat, maxLng, maxLat];
}

// src/svg/paths.ts
function fmt(n) {
  return (Math.round(n * 100) / 100).toString();
}
function geometryToPath(geom, projection) {
  let d = "";
  eachRing(geom, (ring) => {
    let i = 0;
    for (const [lng, lat] of ring) {
      const [x, y] = projection.project(lng, lat);
      d += (i === 0 ? "M" : "L") + fmt(x) + " " + fmt(y);
      i++;
    }
    d += "Z";
  });
  return d;
}
function featurePaths(features, projection) {
  const out = [];
  for (const f of features) {
    const d = geometryToPath(f.geometry, projection);
    if (d) out.push({ d, properties: f.properties });
  }
  return out;
}

export { bboxOf, featurePaths, fitProjection, geometryToPath };
